<div class="form-section"><div class="form-section-title"><span>01</span><div><h3>Course details</h3><p>Give this course a clear identity in the catalogue</p></div></div><div class="form-grid"><label>Course code <em>*</em><input name="course_code" value="{{ old('course_code',$course->course_code) }}" placeholder="e.g. BUC3105" required></label><label>Course title <em>*</em><input name="title" value="{{ old('title',$course->title) }}" placeholder="Enter course title" required></label><label>Credit units <em>*</em><input type="number" min="1" max="20" name="credit_units" value="{{ old('credit_units',$course->credit_units ?: 3) }}" required></label><label>Semester <em>*</em><select name="semester" required>@foreach(['Semester I','Semester II','Recess'] as $sem)<option @selected(old('semester',$course->semester)===$sem)>{{ $sem }}</option>@endforeach</select></label><label>Academic year <em>*</em><input name="academic_year" value="{{ old('academic_year',$course->academic_year ?: '2026/2027') }}" placeholder="2026/2027" required></label><label>Registration capacity <em>*</em><input type="number" min="1" name="capacity" value="{{ old('capacity',$course->capacity ?: 100) }}" required></label><label class="full-field">Description<textarea name="description" rows="3" placeholder="Short course description…">{{ old('description',$course->description) }}</textarea></label><label>Assigned lecturer<select name="lecturer_id"><option value="">No lecturer assigned</option>@foreach($lecturers as $lecturer)<option value="{{ $lecturer->id }}" @selected(old('lecturer_id',$course->lecturer_id)==$lecturer->id)>{{ $lecturer->name }}</option>@endforeach</select></label></div></div>